<template><q-page class="page"><p class="eyebrow">ADMINISTRAÇÃO</p><div class="heading"><div><h1>Auditoria de questões</h1><p>Última execução determinística. Nenhuma correção é aplicada nesta tela.</p></div><q-btn outline no-caps color="primary" icon="refresh" label="Atualizar" :loading="loading" @click="() => load()"/></div><q-banner v-if="error" rounded class="error">{{ error }}</q-banner><q-inner-loading :showing="loading" color="primary"/><q-card v-if="report" flat class="report"><q-card-section><div class="meta"><q-badge color="primary" :label="statusLabel(report.status)"/><span>Algoritmo {{ report.algorithmVersion }}</span><span>Concluída: {{ format(report.finishedAt ?? report.createdAt) }}</span></div><h2>{{ report.scope === 'PUBLISHED' ? 'Questões publicadas' : report.scope }}</h2><div class="summary"><div v-for="(count, status) in report.summary" :key="status" class="metric"><strong>{{ count }}</strong><span>{{ label(status) }}</span></div></div><p v-if="report.errorMessage" class="failure">{{ report.errorMessage }}</p></q-card-section></q-card><q-card v-if="findings" flat class="findings"><q-card-section><div class="findings-head"><h2>Achados ({{ findings.total }})</h2><span>Página {{ findings.page }} de {{ findings.totalPages }}</span></div><q-list bordered separator><q-item v-for="finding in findings.items" :key="finding.id"><q-item-section><q-item-label><q-badge color="primary" :label="label(finding.code)"/> <q-badge outline color="grey-7" :label="finding.confidence"/></q-item-label><q-item-label caption>{{ finding.message }}</q-item-label><q-item-label v-if="finding.structureAfter?.rendering" caption>Proposta de apresentação: {{ finding.structureAfter.rendering }}</q-item-label><q-item-label caption>Questão {{ finding.questionId }} · PDF {{ finding.sourcePdfJobId ?? "não informado" }} · página {{ finding.sourcePage ?? "não informada" }} · {{ label(finding.status) }}</q-item-label></q-item-section></q-item></q-list><q-pagination v-if="findings.totalPages > 1" class="pagination" :model-value="findings.page" :max="findings.totalPages" direction-links boundary-links @update:model-value="goTo"/></q-card-section></q-card><q-card v-else-if="!loading" flat class="empty"><q-card-section>Nenhum relatório de auditoria disponível.</q-card-section></q-card></q-page></template>
<script setup lang="ts">
import { onMounted } from 'vue'
import { useQuestionAudit } from './useQuestionAudit'
const { error, findings, goTo, load, loading, report } = useQuestionAudit(); const format = (value:string):string => new Intl.DateTimeFormat('pt-BR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)); const label=(value:string):string=>value.toLowerCase().replace(/_/g,' '); const statusLabel=(value:string):string=>value==='COMPLETED'?'Concluída':value==='FAILED'?'Falhou':'Em processamento'; onMounted(load)
</script>
