.page{max-width:1080px;margin:auto;padding:42px 34px}.eyebrow{margin:0 0 7px;color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.heading{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:22px}.heading h1{margin:0;color:#142950;font-size:32px}.heading p{margin:8px 0 0;color:#71819e}.report,.empty{border:1px solid #e5ecf6;border-radius:17px;background:#fff;box-shadow:0 8px 26px rgba(33,58,105,.04)}.meta{display:flex;flex-wrap:wrap;gap:10px;align-items:center;color:#71819e;font-size:13px}.report h2{margin:24px 0 14px;color:#1b315a;font-size:19px}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.metric{padding:16px;border-radius:13px;background:#f5f8fe}.metric strong,.metric span{display:block}.metric strong{color:#1d62bf;font-size:28px}.metric span{margin-top:5px;color:#5b7092;font-size:12px;text-transform:capitalize}.findings{margin-top:18px;border:1px solid #e5ecf6;border-radius:17px}.findings h2{margin:0;color:#1b315a;font-size:19px}.findings-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px;color:#71819e;font-size:13px}.findings .q-item{padding:12px 0}.pagination{display:flex;justify-content:center;margin-top:16px}.failure,.error{color:#ae2f25}.error{margin-bottom:16px;background:#fff3f2}@media(max-width:660px){.page{padding:28px 16px}.heading{flex-direction:column}.heading h1{font-size:27px}}
